#!/usr/bin/env python3
"""Mux narration/music/subtitles onto the silent MP4 generated by render_video.py."""
import argparse, shutil, subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--video',default=str(ROOT/'output'/'episode-silent.mp4'));p.add_argument('--voice',default=str(ROOT/'output'/'audio'/'narration.wav'));p.add_argument('--music');p.add_argument('--subtitles');p.add_argument('--output',default=str(ROOT/'output'/'episode-final.mp4'));p.add_argument('--music-volume',type=float,default=.12);a=p.parse_args()
ffmpeg=shutil.which('ffmpeg')
if not ffmpeg: raise SystemExit('FFmpeg não foi encontrado no PATH.')
cmd=[ffmpeg,'-y','-i',a.video]
if a.voice and Path(a.voice).exists(): cmd+=['-i',a.voice]
else: raise SystemExit(f'Áudio de narração não encontrado: {a.voice}')
if a.music and Path(a.music).exists(): cmd+=['-i',a.music]
filters=[]; audio_inputs=[]
voice_idx=1; audio_inputs.append(f'[{voice_idx}:a]volume=1.0,apad[voice]')
if a.music and Path(a.music).exists():
    music_idx=2; audio_inputs.append(f'[{music_idx}:a]volume={max(0,min(a.music_volume,1))}[music]');filters.append(';'.join(audio_inputs)+';[voice][music]amix=inputs=2:duration=first:dropout_transition=2[aout]')
else: filters.append('[1:a]apad[aout]')
cmd+=['-filter_complex',';'.join(filters),'-map','0:v:0','-map','[aout]']
if a.subtitles and Path(a.subtitles).exists():
    subtitle_path=str(Path(a.subtitles).resolve()).replace('\\','/').replace(':','\\:')
    cmd+=['-vf',f'subtitles={subtitle_path}']
cmd+=['-c:v','libx264','-preset','fast','-crf','20','-pix_fmt','yuv420p','-c:a','aac','-b:a','192k','-shortest','-movflags','+faststart',a.output]
subprocess.run(cmd,check=True);print(f'Vídeo final salvo em: {a.output}')
